changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Belgique – Moniteur belge (nominations et démissions)', 'Arrêtés royaux, ministériels et judiciaires de nomination, renouvellement, démission et retraite des hautes fonctions publiques (catégories BE-d, BE-f, BE-g, BE-a)', 'be_pep_moniteur', 'PEP', 'https://www.ejustice.just.fgov.be/cgi/summary.pl?language=fr', 'be-pep-moniteur', 'D:/test parser 2/plugins/swiftcheck-aml-be-pep-moniteur-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"baseUrl": "https://www.ejustice.just.fgov.be/cgi", "days": "30", "delayMs": "1000", "yearsAfterEnd": "5"}', 24, 60, 'Domaine public (Service public fédéral Justice)', 'Moniteur belge (ejustice.just.fgov.be)', 'Collecte quotidienne des actes officiels de nomination et de cessation de fonction parus au Moniteur belge.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Magistrats du siège et du parquet de la Cour de cassation (nominations, renouvellements, retraites).', 'Délai de publication officiel.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-d' AND f.label LIKE 'Conseiller à la Cour de cassation%' AND p.dataset_name = 'be_pep_moniteur';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Conseillers et magistrats suppléants des cours d’appel et des cours du travail.', 'Délai de publication officiel.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-d' AND f.label LIKE 'Conseiller à une cour d''appel%' AND p.dataset_name = 'be_pep_moniteur';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Membres du Conseil d’État (premiers présidents, présidents, conseillers, assesseurs, auditeurs).', 'Délai de publication officiel.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-d' AND f.label LIKE 'Membre du Conseil d''État%' AND p.dataset_name = 'be_pep_moniteur';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Ambassadeurs, consuls généraux et chargés d’affaires nommés par arrêté royal.', 'Délai de publication officiel.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-f' AND f.label LIKE 'Ambassadeur, consul%' AND p.dataset_name = 'be_pep_moniteur';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Officiers généraux de la Défense (général, lieutenant-général, général-major, amiral).', 'Délai de publication officiel.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-f' AND f.label LIKE 'Officier général%' AND p.dataset_name = 'be_pep_moniteur';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Commissaires du gouvernement et administrateurs nommés par arrêté royal ou ministériel.', 'Complété par be_pep_public_enterprises (listes déclarées).' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-g' AND f.label LIKE 'Dirigeant, administrateur ou commissaire du gouvernement%' AND p.dataset_name = 'be_pep_moniteur';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Anciens membres des gouvernements fédéral et régionaux (arrêtés de démission acceptée).', 'Couvre les démissions publiées depuis la date paramétrée.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-a' AND f.label LIKE 'Ancien membre d''un gouvernement%' AND p.dataset_name = 'be_pep_moniteur';
